import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Assumption } from '../types'

const PANE = 'assumptions'
const list = atom({ plugin: 'assumption-session', key: 'list' } as const, [])
const TOOL = 'mcp__assumption-session__record_assumption'

const RULES = `Sempre que, ao construir ou decidir algo, você assumir algo que o usuário não disse explicitamente (uma escolha de tecnologia, um comportamento, um valor padrão, uma interpretação do pedido), chame a ferramenta ${TOOL} com uma frase curta descrevendo a suposição, antes de seguir adiante. Não pare para perguntar: registre e continue. Se o usuário corrigir uma suposição, ajuste o trabalho conforme a correção.`

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.tool.register({
      name: 'record_assumption',
      description: 'Registra uma suposição feita durante o trabalho para o usuário revisar no painel de suposições.',
      inputSchema: {
        type: 'object',
        properties: { assumption: { type: 'string', description: 'A suposição, em uma frase curta.' } },
        required: ['assumption'],
      },
    })
    await $.command.register({ name: 'suposicoes', description: 'Abre o painel de suposições do Claude' })

    return next(e)
  })

  on('command.run', { command: 'suposicoes' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Suposições' })

    return { text: 'Painel de suposições aberto.' }
  })

  on('prompt.compose', async ($, e, next) => {
    const r = await next(e)

    return { sections: [...r.sections, { id: 'assumption-session', text: RULES, scope: 'session' as const }] }
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const text = String((e as { assumption?: string }).assumption ?? '').trim()
    if (text) {
      const a: Assumption = { id: e.tool_use_id, text, status: 'pending' }
      await update($, list, l => [...l, a])
      $.ui.toast('Nova suposição registrada (/suposicoes)')
    }

    return { text: 'Suposição registrada. Continue; o usuário pode corrigi-la depois.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const items = await read($, list)
    const mark = (id: string, status: Assumption['status']) =>
      update($, list, l => l.map(a => (a.id === id ? { ...a, status } : a)))

    return (
      <Box flexDirection="column">
        {items.length === 0 && <Text dimColor>Nenhuma suposição ainda.</Text>}
        {items.map(a => (
          <Box key={a.id} flexDirection="column" marginBottom={1}>
            <Text color={a.status === 'ok' ? 'green' : a.status === 'wrong' ? 'red' : 'yellow'}>
              {a.status === 'ok' ? '✓' : a.status === 'wrong' ? '✗' : '?'} {a.text}
            </Text>
            <Box>
              <Button key={`ok-${a.id}`} label="Certo" onPress={() => mark(a.id, 'ok')} />
              <Text> </Text>
              <Button
                key={`no-${a.id}`}
                label="Corrigir"
                onPress={async () => {
                  await mark(a.id, 'wrong')
                  await $.prompt.fill({
                    text: `Sobre a suposição "${a.text}": está errada. O correto é: `,
                    mode: 'replace',
                  })
                }}
              />
            </Box>
          </Box>
        ))}
      </Box>
    )
  })
}

